namespace exdevice {

	export interface ExDeviceParam {
		[key: string]: any
	}

	export interface ExDeviceRequest {
		service: string;
		requestKey: string;
		param: ExDeviceParam
	}

	export interface ExDeviceResponse {
		service: string;
		requestKey: string;
		statusCode: string;
		return: ExDeviceParam;
	}

	export interface ExDeviceError {
		message: string;
		event: Event;
		exception: any;
	}

	export class Connector {
		/**
		 * 기본 eXDevice+ 접속 포트
		 */
		public static readonly DEFAULT_PORT: number = 13440;
		/**
		 * 기본 eXDevice+ 포트 범위
		 */
		public static readonly DEFAULT_RANGE: number = 10;


		private _handlers: { [key: string]: (response: ExDeviceResponse) => void };
		private _port: number;
		private _portRange: number;
		private _ws: WebSocket;
		private _connected: boolean = false;
		private _state: State = State.CLOSED;

		private _messageHandler: (data: any) => void;
		private _readyHandler: (connector: Connector) => void;
		private _errorHandler: (err: ExDeviceError) => void;
		private _closeHandler: (connector: Connector) => void;


		constructor(portNumber: number, portRange: number) {
			this._handlers = {};
			this._port = portNumber != null && portNumber > 0 ? portNumber : Connector.DEFAULT_PORT;
			this._portRange = portRange != null && portRange > 0 ? portRange : Connector.DEFAULT_RANGE;
		}

		public set onmessage(messageHandler: (data: any) => void) {
			this._messageHandler = messageHandler;
		}

		public set onready(readyHandler: (connector: Connector) => void) {
			this._readyHandler = readyHandler;
		}

		public set onerror(errorHandler: (err: ExDeviceError) => void) {
			this._errorHandler = errorHandler;
		}

		public set onclose(closeHandler: (connector: Connector) => void) {
			this._closeHandler = closeHandler;
		}

		public getState(): State {
			return this._state;
		}

		public isConnected(): boolean {
			return this._connected;
		}

		public connect(): void {
			if (this.isConnected()) {
				console.log("already connected");
				if (this._readyHandler) {
					this._readyHandler(this);
				}
				return;
			}

			let _tryCnt: number = 0;
			let _scanPort: number = this._port;

			this._state = State.CONNECTING;
			this._connected = false;

			let portScan: FrameRequestCallback = (time: number) => {
				_tryCnt++;

				let retryConnection: Function = () => {
					if (_tryCnt >= this._portRange) {
						console.log("port scan fail");
						this._state = State.CLOSED;
						this._connected = false;

						if (this._errorHandler) {
							this._errorHandler(this._createExDeviceError("connection fail", null, null));
						}

						return;
					}
					_scanPort++;

					window.requestAnimationFrame(portScan);
				}

				console.log("try connect " + _scanPort);
				this._ws = new WebSocket("wss://127.0.0.1:" + _scanPort);
				this._ws.onopen = (ev: Event) => {
					console.log("open : " + _scanPort);

					let req: {} = { service: "eXDeviceInfo", requestKey: "1", param: {} };

					this._ws.send(JSON.stringify(req));
				};
				this._ws.onmessage = (ev: MessageEvent) => {
					try {
						console.log(ev.data);
						let res: {} = JSON.parse(ev.data);
						if (res["return"]["name"] == "eXDevicePlus") {
							this._setupConnection();
							return;
						}

					} catch (err) {
						console.log("other app");
						try {
							this._ws.close();
						} catch (er) { }

						retryConnection();
					}
				}
				this._ws.onerror = (ev: Event) => {
					console.log("error occur");

					try {
						this._ws.close();
					} catch (er) { }

					retryConnection();
				};
			};

			portScan(0);
		}

		public send(serviceId: string, param: ExDeviceParam, handler: (response: ExDeviceResponse) => void, once: boolean = false): string {
			if (this._state != State.OPEN) {
				throw new Error("eXDevice+ is not connected");
			}
			let reqKey: string = this._createRequestKey();
			let request: ExDeviceRequest = {
				service: serviceId,
				requestKey: reqKey,
				param: param
			};

			if (once === true) {
				this._handlers[reqKey] = (response: ExDeviceResponse) => {
					handler(response);
					delete this._handlers[reqKey];
				};
			} else {
				this._handlers[reqKey] = handler;
			}
			let requestTxt: string = JSON.stringify(request);

			this._ws.send(requestTxt);

			return reqKey;
		}

		public removeHandler(reqKey: string): void {
			delete this._handlers[reqKey];
		}

		public removeAllHandlers(): void {
			this._handlers = {};
		}

		public close(): void {
			if (this.isConnected()) {
				this._state = State.CLOSING;
				this._connected = false;
				this._ws.close();
			}
		}

		private _setupConnection(): void {
			this._ws.onmessage = (ev: MessageEvent) => {
				this._onMessage.apply(this, [ev]);
			}
			this._ws.onerror = (ev: Event) => {
				this._onError.apply(this, [ev]);
			}
			this._ws.onclose = (ev: CloseEvent) => {
				this._onClose.apply(this, [ev]);
			}

			this._state = State.OPEN;
			this._connected = true;

			if (this._readyHandler) {
				this._readyHandler(this);
			}
		}

		private _onMessage(ev: MessageEvent): void {
			let data: any = ev.data;
			if (data == null || data == "") {
				return;
			}
			try {
				let handler: (msg: {}) => void;
				let returnMsg: ExDeviceResponse = JSON.parse(data);
				let reqKey: string = returnMsg.requestKey;
				if (reqKey) {
					handler = this._handlers[reqKey];
					if (handler) {
						handler(returnMsg);
					}
				}
			} catch (err) {
				if (this._errorHandler) {
					this._errorHandler(this._createExDeviceError(null, ev, err));
				} else {
					console.log(err);
				}
			}
			if (this._messageHandler) {
				this._messageHandler(ev.data);
			}
		}

		private _onError(ev: Event): void {
			if (this._errorHandler) {
				this._errorHandler(this._createExDeviceError("Websocket error", ev, null));
			} else {
				console.log(ev);
			}
		}

		private _onClose(ev: CloseEvent): void {
			this._state = State.CLOSED;
			this._connected = false;
			if (this._closeHandler) {
				this._closeHandler(this);
			}
			this._handlers = {};
		}

		private _createRequestKey(): string {
			return this._createRandomStr() + "-" + this._createRandomStr() + "-" + this._createRandomStr();
		}

		private _createRandomStr(): string {
			return Math.floor((1 + Math.random()) * 0x10000).toString(16).substring(1);
		}

		private _createExDeviceError(errMsg: string, errEv: Event, errExcep: any): ExDeviceError {
			return {
				message: errMsg,
				event: errEv,
				exception: errExcep
			}
		}


	}
}